import 'package:cloud_firestore/cloud_firestore.dart';
class AurenSafetyPlace {final String id,name,type,city,country; const AurenSafetyPlace({required this.id,required this.name,required this.type,required this.city,required this.country}); factory AurenSafetyPlace.fromDoc(DocumentSnapshot<Map<String,dynamic>> d){final x=d.data()??{};return AurenSafetyPlace(id:d.id,name:x['name']??'',type:x['type']??'emergency',city:x['city']??'',country:x['country']??'');}}
class AurenOfflineSafetyService {AurenOfflineSafetyService._();static final instance=AurenOfflineSafetyService._();final _db=FirebaseFirestore.instance;
Stream<List<AurenSafetyPlace>> watchPlaces({String city='',String country=''})=>_db.collection('safety_places').where('active',isEqualTo:true).limit(100).snapshots().map((s){final c=city.toLowerCase().trim(),co=country.toLowerCase().trim();return s.docs.map(AurenSafetyPlace.fromDoc).where((x)=>(c.isEmpty||x.city.toLowerCase()==c)&&(co.isEmpty||x.country.toLowerCase()==co)).toList();});
Future<String> saveRoute({required String uid,required String name,required List<Map<String,double>> points})async{if(uid.isEmpty||name.trim().isEmpty||points.length<2||points.length>500)throw ArgumentError('بيانات المسار غير صالحة.');final ref=_db.collection('users').doc(uid).collection('offline_routes').doc();await ref.set({'ownerId':uid,'name':name.trim(),'points':points,'createdAt':FieldValue.serverTimestamp()});return ref.id;}
Stream<QuerySnapshot<Map<String,dynamic>>> watchRoutes(String uid)=>_db.collection('users').doc(uid).collection('offline_routes').limit(50).snapshots();}
